/* Generated by Trae Work */
/* 仪表盘：今日学习计划（按课表排序，每节课=一个章节小节进度单元）+ 打卡云端监视（ntfy.sh 频道实时同步） */
"use strict";
(function () {
  const S = window.ScheduleAPI;

  function todayISO() {
    const d = new Date(); return fmtDate(d);
  }
  function blockStatus(b) {
    const ov = Store.get("block_overrides", {});
    return ov[b.id] ? ov[b.id].status : "pending";
  }
  function setStatus(b, status, reason) {
    const ov = Store.get("block_overrides", {});
    if (status === "pending") delete ov[b.id];
    else ov[b.id] = {
      status, reason: reason || "",
      done_at: status === "done"
        ? (ov[b.id] && ov[b.id].done_at) || new Date().toLocaleString("zh-CN", { hour12: false })
        : (ov[b.id] && ov[b.id].done_at) || ""
    };
    Store.set("block_overrides", ov);
  }
  function doneAtOf(b) {
    const ov = Store.get("block_overrides", {});
    return (ov[b.id] && ov[b.id].done_at) || "";
  }
  /* ---------- 笔记照片（压缩后经 ntfy.sh 附件上传，随快照保留约 12 小时） ---------- */
  function photoOf(id) {
    const p = Store.get("lesson_photos", {})[id];
    return p && p.date === todayISO() ? p : null;
  }
  function setPhoto(id, url) {
    const m = Store.get("lesson_photos", {});
    m[id] = { date: todayISO(), url, ts: new Date().toLocaleString("zh-CN", { hour12: false }) };
    Store.set("lesson_photos", m);
  }
  function compressImage(file) {
    return new Promise((res, rej) => {
      const img = new Image();
      img.onload = () => {
        try {
          const max = 1280, scale = Math.min(1, max / Math.max(img.width, img.height));
          const c = document.createElement("canvas");
          c.width = Math.round(img.width * scale); c.height = Math.round(img.height * scale);
          c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
          c.toBlob(b => b ? res(b) : rej(new Error("压缩失败")), "image/jpeg", 0.72);
        } catch (e) { rej(e); }
      };
      img.onerror = () => rej(new Error("图片读取失败"));
      img.src = URL.createObjectURL(file);
    });
  }
  async function uploadPhoto(topic, blob, name) {
    const res = await fetchTimeout(CLOUD + "/" + topic, {
      method: "POST",
      headers: { "X-Filename": name, "X-Title": "Study Note", "Accept": "application/json" },
      body: blob
    });
    if (!res.ok) throw new Error("HTTP " + res.status);
    const j = await res.json();
    if (!j.attachment || !j.attachment.url) throw new Error("未返回附件地址");
    return j.attachment.url;
  }
  function buildPayload(blocks, name) {
    const lessons = blocks.map(b => {
      const st = blockStatus(b);
      const ph = photoOf(b.id);
      return {
        time: `${S.PERIODS[b._p].start}–${S.PERIODS[b._p].end}`,
        label: `${subjectName(b.subject)} · ${b.content_title}`,
        track: b.track,
        status: st,
        done_at: st === "done" ? doneAtOf(b) : "",
        photos: ph ? [ph.url] : []
      };
    });
    const done = lessons.filter(l => l.status === "done").length;
    const skipped = lessons.filter(l => l.status === "skipped").length;
    return {
      app: "yyy-prep-checkin",
      name: name || "匿名学习者",
      date: todayISO(),
      updated_at: new Date().toLocaleString("zh-CN", { hour12: false }),
      summary: { total: lessons.length, done, skipped, pending: lessons.length - done - skipped, percent: lessons.length ? Math.round(done / lessons.length * 100) : 0 },
      lessons
    };
  }

  /* ---------- 云端同步（ntfy.sh 公开频道：免注册、国内可达、SSE 实时；快照保留约 12 小时） ---------- */
  function todayPlanBlocks() {
    const ws = S.mondayOf(new Date());
    return S.generateDay(todayISO(), fmtDate(ws), S.weekIdxOf(ws));
  }
  const CLOUD = "https://ntfy.sh";

  function fetchTimeout(url, opts = {}, ms = 12000) {
    const c = new AbortController();
    const t = setTimeout(() => c.abort(), ms);
    return fetch(url, { ...opts, signal: c.signal }).finally(() => clearTimeout(t));
  }

  function todayTopic() {
    let t = Store.get("checkin_topic", "");
    if (!t) {
      const a = new Uint8Array(10);
      (crypto || {}).getRandomValues ? crypto.getRandomValues(a) : a.forEach((_, i) => a[i] = Math.floor(Math.random() * 256));
      t = "yyy-prep-" + [...a].map(x => x.toString(16).padStart(2, "0")).join("");
      Store.set("checkin_topic", t);
    }
    return t;
  }

  async function pushCloud(silent) {
    const blocks = todayPlanBlocks();
    if (!blocks.length) { if (!silent) alert("今天没有课表块（先在课表页选择课程合集）。"); return false; }
    const topic = todayTopic();
    const statusEl = document.getElementById("cloud-status");
    try {
      if (statusEl) statusEl.textContent = "同步中…";
      const res = await fetchTimeout(CLOUD + "/" + topic, {
        method: "POST",
        headers: { "X-Title": "Daily Checkin", "X-Tags": "white_check_mark" },
        body: JSON.stringify(buildPayload(blocks, Store.get("checkin_name", "")))
      });
      if (!res.ok) throw new Error("HTTP " + res.status);
      Store.set("cloud_last_push", new Date().toISOString());
      if (statusEl) statusEl.innerHTML = `<span class="badge ok">已同步</span> 监视链接：<code>status.html?topic=${topic}</code>`;
      renderCloudPanel();
      return true;
    } catch (e) {
      const msg = e.name === "AbortError" ? "请求超时" : e.message;
      if (statusEl) statusEl.innerHTML = `<span class="badge miss">同步失败</span> ${msg}（可稍后重试）`;
      if (!silent) alert("打卡同步失败：" + msg);
      return false;
    }
  }

  function renderCloudPanel() {
    const root = document.getElementById("cloud-panel");
    if (!root) return;
    const hasTopic = !!Store.get("checkin_topic", "");
    const name = Store.get("checkin_name", "");
    const last = Store.get("cloud_last_push", "");
    const auto = Store.get("cloud_auto", true);
    root.innerHTML = `
      <h3>打卡监视（云端）</h3>
      <p class="muted">打卡后状态发布到 ntfy.sh 的<strong>随机私有频道</strong>（免注册）；对方打开监视链接即可实时看到你的学习状态（SSE 实时推送，快照保留约 12 小时）。仅上传课表完成状态，不含个人隐私。</p>
      <div class="cloud-form">
        <input id="checkin-name" type="text" placeholder="昵称（可选）" value="${name}" maxlength="20">
        <button class="btn" id="checkin-now">立即打卡</button>
        ${hasTopic ? `<button class="btn ghost" id="cloud-copy">复制监视链接</button>
        <a class="btn ghost" href="status.html?topic=${Store.get("checkin_topic", "")}" target="_blank" rel="noopener">打开监视页</a>` : ""}
      </div>
      <label style="font-size:13px;display:block;margin-top:8px;"><input type="checkbox" id="cloud-auto" ${auto ? "checked" : ""}> 完成课程时自动同步到云端</label>
      <div id="cloud-status" style="margin-top:8px;font-size:13px;">${hasTopic
        ? (last ? `上次打卡：${new Date(last).toLocaleString("zh-CN", { hour12: false })} · 频道已就绪` : "已创建私有频道，尚未打卡")
        : "尚未创建私有频道，首次打卡自动创建。"}</div>`;

    document.getElementById("checkin-now").addEventListener("click", () => {
      Store.set("checkin_name", document.getElementById("checkin-name").value.trim());
      pushCloud(false);
    });
    document.getElementById("cloud-auto").addEventListener("change", e => Store.set("cloud_auto", e.target.checked));
    const copy = document.getElementById("cloud-copy");
    if (copy) copy.addEventListener("click", () => {
      const url = location.origin + location.pathname.replace(/[^/]*$/, "") + `status.html?topic=${Store.get("checkin_topic", "")}`;
      (navigator.clipboard ? navigator.clipboard.writeText(url) : Promise.reject()).then(
        () => { copy.textContent = "已复制"; setTimeout(() => copy.textContent = "复制监视链接", 1500); },
        () => prompt("请手动复制监视链接：", url)
      );
    });
  }

  /* ---------- 今日学习计划 ---------- */
  function renderPlan() {
    const root = document.getElementById("today-plan-root");
    if (!root) return;
    const now = new Date();
    const iso = fmtDate(now);
    const blocks = todayPlanBlocks()
      .sort((a, b) => a._p - b._p);

    if (iso < S.SCHEDULE_START) {
      root.innerHTML = `<div class="notice info">排课起始日为 ${S.SCHEDULE_START}，此前无每日计划。</div>`;
      return;
    }
    if (!blocks.length) {
      root.innerHTML = `<div class="notice empty"><strong>今天没有排课。</strong>请到<a href="schedule.html">课表页</a>选择课程合集后回来刷新。</div>`;
      return;
    }
    const done = blocks.filter(b => blockStatus(b) === "done").length;
    const skipped = blocks.filter(b => blockStatus(b) === "skipped").length;
    const pct = Math.round(done / blocks.length * 100);

    const head = `
      <div class="plan-summary">
        <div class="plan-date">${now.getMonth() + 1} 月 ${now.getDate()} 日 · ${S.WEEKDAYS[(now.getDay() + 6) % 7]}</div>
        <div class="plan-pct">${pct}%<small>（${done}/${blocks.length} 节${skipped ? ` · 跳过 ${skipped}` : ""}）</small></div>
      </div>
      <div class="prog big"><div class="prog-fill" style="width:${pct}%"></div></div>`;

    const cards = blocks.map(b => {
      const st = blockStatus(b);
      const ph = photoOf(b.id);
      const pd = S.PERIODS[b._p];
      return `
      <div class="plan-lesson ${b.track} ${st}" data-id="${b.id}">
        <div class="pl-head">
          <span class="pl-time">${S.SLOT_NAMES[pd.slot]} ${pd.label}<br><strong>${pd.start}–${pd.end}</strong></span>
          <div class="pl-goal">
            <div class="pl-goal-label">今天要完成：</div>
            <div class="pl-goal-text">${badge(b.track)} ${subjectName(b.subject)} · ${b.content_title}</div>
          </div>
          <span class="badge ${st === "done" ? "ok" : st === "skipped" ? "miss" : "warnb"}">${st === "done" ? "已完成" : st === "skipped" ? "已跳过" : "待完成"}</span>
        </div>
        <div class="prog"><div class="prog-fill" style="width:${st === "done" ? 100 : 0}%"></div></div>
        ${ph ? `<div class="pl-photos"><a href="${ph.url}" target="_blank" rel="noopener"><img src="${ph.url}" alt="打卡笔记照片"></a><span class="muted pl-ts">笔记 ${ph.ts}</span></div>` : ""}
        ${st === "done" && !ph && doneAtOf(b) ? `<div class="muted pl-ts">打卡时间：${doneAtOf(b)}</div>` : ""}
        <div class="pl-actions">
          ${st !== "done" ? `<button class="btn small" data-act="done" data-id="${b.id}">完成（100%）</button>` : `<button class="btn small ghost" data-act="reset" data-id="${b.id}">撤销完成</button>`}
          ${st !== "skipped" && st !== "done" ? `<button class="btn small ghost" data-act="skip" data-id="${b.id}">跳过</button>` : ""}
          <label class="btn small ghost pl-photo-btn">📷 笔记打卡<input type="file" accept="image/*" hidden data-photo="${b.id}"></label>
        </div>
      </div>`;
    }).join("");

    root.innerHTML = head + cards;

    root.querySelectorAll("button[data-act]").forEach(btn => {
      btn.addEventListener("click", async () => {
        const id = btn.dataset.id, act = btn.dataset.act;
        if (act === "done") setStatus(blocks.find(b => b.id === id), "done");
        else if (act === "skip") setStatus(blocks.find(b => b.id === id), "skipped", prompt("跳过原因（可选）：") || "");
        else setStatus(blocks.find(b => b.id === id), "pending");
        renderPlan();
        if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) await pushCloud(true);
      });
    });

    /* 笔记照片：压缩上传后自动完成该节打卡 */
    root.querySelectorAll("input[data-photo]").forEach(inp => {
      inp.addEventListener("change", async () => {
        const id = inp.dataset.photo;
        const f = inp.files && inp.files[0];
        if (!f) return;
        const b = blocks.find(x => x.id === id);
        const st = document.getElementById("cloud-status");
        try {
          if (st) st.textContent = "笔记照片上传中…";
          const blob = await compressImage(f);
          const url = await uploadPhoto(todayTopic(), blob, "note-" + id.replace(/[^a-zA-Z0-9]/g, "") + "-" + Date.now() + ".jpg");
          setPhoto(id, url);
          if (b) setStatus(b, "done");
          if (st) st.innerHTML = `<span class="badge ok">笔记已上传，已完成该节打卡</span>`;
          renderPlan();
          if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) await pushCloud(true);
        } catch (e) {
          const msg = e.name === "AbortError" ? "请求超时" : e.message;
          if (st) st.innerHTML = `<span class="badge miss">笔记上传失败</span> ${msg}（可稍后重试）`;
        }
      });
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
    if (!document.getElementById("today-plan-root")) return;
    renderPlan();
    renderCloudPanel();
    /* 已有私有频道且开自动同步：进页静默同步一次 */
    if (Store.get("cloud_auto", true) && Store.get("checkin_topic", "")) pushCloud(true);
    const refresh = document.getElementById("plan-refresh");
    if (refresh) refresh.addEventListener("click", renderPlan);
  });
})();
